-- landing table's ingestion timestamp is named INGESTED_AT (no leading underscore) rather than the usual _INGESTED_AT -- confirmed via INFORMATION_SCHEMA, not assumed.

with source as (

    select * from {{ source('ripple_raw', 'PORTAL_ARC_OPEN_DATA_MINNEA_0426858DFE') }}

),

renamed as (

    select
        "OBJECTID" as objectid,
        "CONTROLNBR" as controlnbr,
        "CITYCODE" as citycode,
        "CASEYEAR" as caseyear,
        "CASENBR" as casenbr,
        "CCN" as ccn,
        "OFFENSE" as offense,
        "UCRCODE" as ucrcode,
        "REPORTEDDATE" as reporteddate,
        "BEGINDATE" as begindate,
        "DAY" as day,
        "MONTH" as month,
        "YEAR" as year,
        "TIME" as time,
        "HOUR" as hour,
        "PRECINCT" as precinct,
        "ADDRESS" as address,
        "CITY" as city,
        "STATE" as state,
        "ZIPCODE" as zipcode,
        "ENTEREDDATE" as entereddate,
        "ENDDATE" as enddate,
        "X" as x,
        "Y" as y,
        "LAT" as lat,
        "LONG" as long,
        "GEOMETRY" as geometry,
        INGESTED_AT as _loaded_at,
        'https://opendata.minneapolismn.gov/datasets/dda28ccd6ef54114967d88f7c701f91c_0' as _source_url,
    'ENT_' || LEFT(MD5('CCN' || '|' || (CASE WHEN LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN"), '[^0-9A-Za-z]', ''))) = 0 OR LENGTH(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN"), '[^0-9A-Za-z]', ''))) > 6 OR LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN"), '[^0-9A-Za-z]', '')), 6, '0') = REPEAT('0', 6) THEN NULL ELSE LPAD(UPPER(REGEXP_REPLACE(TO_VARCHAR("CCN"), '[^0-9A-Za-z]', '')), 6, '0') END)), 16) as spine_entity_id  -- joins LIBRARY_META."CONNECT".ENTITY_GOLDEN.ENTITY_ID

    from source

)

select * from renamed
qualify row_number() over (partition by ccn order by _loaded_at desc) = 1
